 internal static Dictionary<string,object> Parse(string text){return JSON.Deserialize<Dictionary<string,object>>(text);}
 internal static List<Dictionary<string,object>> Rows(object value){return ((IEnumerable)value).Cast<object>().Select(v=>(Dictionary<string,object>)v).ToList();}
 internal static string ReadResource(string name){using(var r=new StreamReader(Assembly.GetExecutingAssembly().GetManifestResourceStream(name)))return r.ReadToEnd();}
 internal static string Hash(string file){using(var s=File.OpenRead(file))using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(s)).Replace("-","").ToLowerInvariant();}
 internal static bool Valid(string path,Dictionary<string,object> info){return File.Exists(path)&&new FileInfo(path).Length==Convert.ToInt64(info["bytes"])&&Hash(path)==(string)info["sha256"];}
 internal static string Canonical(object value){var d=value as Dictionary<string,object>;if(d!=null)return "{"+string.Join(",",d.OrderBy(p=>p.Key,StringComparer.Ordinal).Select(p=>JSON.Serialize(p.Key)+":"+Canonical(p.Value)))+"}";var a=value as IList;if(a!=null)return "["+string.Join(",",a.Cast<object>().Select(Canonical))+"]";return JSON.Serialize(value);}
 internal static string DefaultData(){string fallback=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"Zotero"),profiles=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),"Zotero","Zotero","Profiles");try{if(Directory.Exists(profiles))foreach(var folder in Directory.GetDirectories(profiles).OrderBy(x=>x)){var prefs=Path.Combine(folder,"prefs.js");if(!File.Exists(prefs))continue;var m=Regex.Match(File.ReadAllText(prefs),"user_pref\\(\"extensions\\.zotero\\.dataDir\",\\s*(\"(?:\\\\.|[^\"\\\\])*\")");if(m.Success){var dir=JSON.Deserialize<string>(m.Groups[1].Value);if(File.Exists(Path.Combine(dir,"zotero.sqlite")))return dir;}}}catch(IOException){}return fallback;}
 internal static string ModelRoot(string data){try{var path=Path.Combine(data,"paper-nexus-model-location.json");if(File.Exists(path)&&new FileInfo(path).Length<16384){var record=Parse(File.ReadAllText(path));var root=(string)record["root"];if(Convert.ToInt32(record["schema"])==1&&Path.IsPathRooted(root))return root;}}catch(Exception){}return Path.Combine(data,"paper-nexus-models");}
 internal static void AtomicWrite(string path,string content){var temp=path+".tmp-"+Guid.NewGuid().ToString("N");File.WriteAllText(temp,content,new UTF8Encoding(false));try{if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}}
