 [STAThread] static int Main(){ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;try{if(Flag("--quiet")){if(Flag("--plugin-only")){if(Arg("--download-dir")==null)throw new Exception("Download directory required");using(var engine=new Engine()){if(Flag("--cancel-test"))engine.Progress=(phase,p)=>{if(p>0)engine.Cancel();};var file=engine.DownloadPlugin(Arg("--download-dir")).GetAwaiter().GetResult();if(Arg("--result")!=null)File.WriteAllText(Arg("--result"),file);return 0;}}var ids=(Arg("--model")??"minilm").Split(',');var chosen=ids.Select(id=>Models.First(m=>(string)m["id"]==id)).ToList();if(Arg("--data-dir")==null||Arg("--download-dir")==null)throw new Exception("Explicit data and download directories required");using(var engine=new Engine()){if(Flag("--cancel-test"))engine.Progress=(phase,p)=>{if(phase=="model"&&p>0.08)engine.Cancel();};string file=null;foreach(var model in chosen)file=engine.Install(model,Arg("--data-dir"),Arg("--download-dir"),Arg("--model-dir")).GetAwaiter().GetResult();if(Arg("--result")!=null)File.WriteAllText(Arg("--result"),file);return 0;}}Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.Run(new Installer());return 0;}catch(Exception e){if(Arg("--result")!=null)File.WriteAllText(Arg("--result"),e.Message);return 1;}}
