internal sealed class Engine:IDisposable {
 readonly CancellationTokenSource stop=new CancellationTokenSource();internal Action<string,double> Progress;internal bool Cancelled {get{return stop.IsCancellationRequested;}}internal void Cancel(){stop.Cancel();}public void Dispose(){stop.Dispose();}
 void Check(){stop.Token.ThrowIfCancellationRequested();}
 void Report(string phase,double p){Check();if(Progress!=null)Progress(phase,p);}
 void Verify(string folder,Dictionary<string,object> manifest){foreach(var f in Setup.Rows(manifest["files"])){Check();string name=(string)f["name"];if(Path.GetFileName(name)!=name||!Setup.Valid(Path.Combine(folder,name),f))throw new Exception("模型校验失败 / Model verification failed");}}
 async Task Fetch(Dictionary<string,object> asset,string target,string phase="model"){Check();var uri=new Uri((string)asset["url"]);if(uri.Scheme!="https")throw new Exception("HTTPS required");long expected=Convert.ToInt64(asset["bytes"]);var offline=(phase=="plugin"?Setup.Arg("--plugin-dir"):null)??Setup.Arg("--package-dir");if(offline!=null){File.Copy(Path.Combine(offline,(string)asset["name"]),target);Report(phase,phase=="plugin"?1:0.88);}else{
  using(var handler=new HttpClientHandler {AllowAutoRedirect=false})using(var client=new HttpClient(handler)){client.Timeout=TimeSpan.FromMinutes(15);HttpResponseMessage response=null;try{for(int i=0;i<8;i++){response=await client.GetAsync(uri,HttpCompletionOption.ResponseHeadersRead,stop.Token);if((int)response.StatusCode<300||(int)response.StatusCode>=400)break;var next=response.Headers.Location;if(next==null)throw new Exception("Missing redirect");uri=next.IsAbsoluteUri?next:new Uri(uri,next);response.Dispose();response=null;if(uri.Scheme!="https")throw new Exception("HTTPS required");}if(response==null||response.StatusCode!=HttpStatusCode.OK)throw new Exception("下载暂不可用 / Download unavailable");using(var input=await response.Content.ReadAsStreamAsync())using(var output=File.Create(target)){byte[] buffer=new byte[65536];long total=0;int count;while((count=await input.ReadAsync(buffer,0,buffer.Length,stop.Token))>0){total+=count;if(total>expected)throw new Exception("Unexpected file size");await output.WriteAsync(buffer,0,count,stop.Token);Report(phase,phase=="plugin"?(double)total/expected:0.08+0.80*total/expected);}}}finally{if(response!=null)response.Dispose();}}}
  Check();if(!Setup.Valid(target,asset))throw new Exception("文件校验失败，请重试 / File verification failed");
 }
 internal async Task<string> DownloadPlugin(string downloads){Directory.CreateDirectory(downloads);var plugin=(Dictionary<string,object>)Setup.Config["plugin"];var xpi=Path.Combine(downloads,(string)plugin["name"]);if(!Setup.Valid(xpi,plugin)){Report("plugin",0);var temp=Path.Combine(downloads,".plugin-"+Guid.NewGuid().ToString("N"));try{await Fetch(plugin,temp,"plugin");Check();if(File.Exists(xpi))File.Replace(temp,xpi,null);else File.Move(temp,xpi);}finally{if(File.Exists(temp))File.Delete(temp);}}Check();Report("plugin",1);return xpi;}
 internal async Task<string> Install(Dictionary<string,object> model,string data,string downloads,string modelDirectory=null){if(!File.Exists(Path.Combine(data,"zotero.sqlite")))throw new Exception("请选择包含 zotero.sqlite 的 Zotero 数据目录 / Choose the Zotero data folder containing zotero.sqlite");var root=modelDirectory??Setup.ModelRoot(data);if(root==Path.Combine(data,"paper-nexus-models"))Directory.CreateDirectory(root);if(!Directory.Exists(root))throw new Exception("模型目录不可用，请重新选择 / Model folder unavailable; choose an existing folder");using(var mutex=new FileStream(Path.Combine(root,".installer.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){var work=Path.Combine(root,".setup-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(work);try{
  var manifest=(Dictionary<string,object>)model["manifest"];var parent=Path.Combine(root,(string)model["id"]);var target=Path.Combine(parent,(string)manifest["version"]);var xpi=await DownloadPlugin(downloads);
  bool usable=false;if(Directory.Exists(target)){Report("verify",0.08);try{Verify(target,manifest);usable=true;}catch(IOException){}catch(Exception){Check();}}
  if(!usable){var asset=(Dictionary<string,object>)model["package"];var archive=Path.Combine(downloads,(string)asset["name"]);if(!Setup.Valid(archive,asset)){var partial=Path.Combine(downloads,".model-"+Guid.NewGuid().ToString("N"));try{await Fetch(asset,partial);if(File.Exists(archive))File.Replace(partial,archive,null);else File.Move(partial,archive);}finally{if(File.Exists(partial))File.Delete(partial);}}Report("verify",0.89);var extracted=Path.Combine(work,"verified");Directory.CreateDirectory(extracted);var files=Setup.Rows(manifest["files"]);var expected=new HashSet<string>(files.Select(f=>(string)f["name"]),StringComparer.Ordinal){"manifest.json"};var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
   using(var zip=ZipFile.OpenRead(archive)){foreach(var entry in zip.Entries){Check();if(!expected.Contains(entry.FullName)||!seen.Add(entry.FullName)||Path.GetFileName(entry.FullName)!=entry.FullName)throw new Exception("Unexpected model archive entry");long limit=entry.FullName=="manifest.json"?4000000:Convert.ToInt64(files.First(f=>(string)f["name"]==entry.FullName)["bytes"]);if(entry.Length>limit)throw new Exception("Unexpected model file size");entry.ExtractToFile(Path.Combine(extracted,entry.FullName));}if(seen.Count!=expected.Count)throw new Exception("Incomplete model package");}
   var actualIdentity=Setup.Parse(File.ReadAllText(Path.Combine(extracted,"manifest.json")));var expectedIdentity=new Dictionary<string,object>(manifest);actualIdentity.Remove("name");expectedIdentity.Remove("name");if(Setup.Canonical(actualIdentity)!=Setup.Canonical(expectedIdentity))throw new Exception("Model manifest mismatch");Verify(extracted,manifest);Report("install",0.97);Directory.CreateDirectory(parent);var backup=Path.Combine(work,"previous");if(Directory.Exists(target))Directory.Move(target,backup);try{Directory.Move(extracted,target);}catch{if(Directory.Exists(backup))Directory.Move(backup,target);throw;}}
  string pointer=Path.Combine(parent,"active.json"),staged=Path.Combine(parent,".active-"+Guid.NewGuid().ToString("N"));File.WriteAllText(staged,Setup.JSON.Serialize(manifest),new UTF8Encoding(false));try{if(File.Exists(pointer))File.Replace(staged,pointer,null);else File.Move(staged,pointer);}finally{if(File.Exists(staged))File.Delete(staged);}Setup.AtomicWrite(Path.Combine(data,"paper-nexus-model-location.json"),Setup.JSON.Serialize(new Dictionary<string,object>{{"schema",1},{"root",Path.GetFullPath(root)}}));if(Progress!=null)Progress("done",1);return xpi;
 }finally{if(Directory.Exists(work))Directory.Delete(work,true);}}}
}
