 }
 void UpdateCard(int index,string phase,double value){modelBars[index].Visible=true;modelBars[index].Value=value;if(phase=="model"){var package=(Dictionary<string,object>)Setup.Models[index]["package"];double total=Convert.ToDouble(package["bytes"]),bytes=Math.Max(0,(value-.08)/.8)*total,seconds=Math.Max(.1,(DateTime.UtcNow-downloadBegan).TotalSeconds);details[index].Text=T("下载中","Downloading")+string.Format(" · {0:F1} / {1:F1} MB · {2:F1} MB/s",bytes/1e6,total/1e6,bytes/seconds/1e6);}else{var names=new Dictionary<string,string>{{"plugin",T("下载插件","Downloading plugin")},{"verify",T("校验中","Verifying")},{"install",T("安装中","Installing")},{"done",T("已安装 · 可在插件中切换","Installed · Available in plugin settings")}};details[index].Text=names[phase];}if(phase=="done"){completed.Add(index);details[index].ForeColor=Visual.Green;modelBars[index].Tint=Visual.Green;modelBars[index].Invalidate();}}
 void RefreshText(){Text=T("Paper Nexus 安装助手","Paper Nexus Installer");heading.Text=T("把文献，连成研究线索。","Connect your research.");intro.Text=T("选择至少一个本地模型，可多选。以后仅更新插件。","Choose one or more models. Update the plugin independently.");for(int i=0;i<options.Count;i++){options[i].Text=(string)Setup.Models[i][zh?"titleZh":"titleEn"];details[i].Text=completed.Contains(i)?T("已安装 · 可在插件中切换","Installed · Available in plugin settings"):(string)Setup.Models[i][zh?"detailZh":"detailEn"];}action.Enabled=!busy&&options.Any(o=>o.Checked);targetLabel.Text=T("模型位置","Model folder");pathLabel.Text=modelDirectory.Replace(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"%USERPROFILE%");folder.Text=T("选择文件夹","Browse");help.Text=T("安装帮助","Help");cancel.Text=T("取消","Cancel");pluginLabel.Text=T("插件 XPI","Plugin XPI")+" · v"+Setup.Version;pluginButton.Text=xpi==null?T("下载插件","Download XPI"):T("打开文件","Show XPI");action.Text=complete?T("打开插件文件夹","Show plugin file"):T("下载插件与模型","Get plugin & models");status.Text=complete?T("模型已就绪。在 Zotero 中从文件安装 XPI，然后在网络设置中选择分析方案。","Model ready. Install the XPI from file in Zotero, then choose an analysis in Network settings."):T("无需账户或管理员权限。文献内容保留在本机。","No account or administrator access. Library content stays local.");}
 void Busy(bool value){busy=value;pluginButton.Enabled=!value;options.ForEach(o=>o.Enabled=!value);folder.Enabled=language.Enabled=action.Enabled=!value;cancel.Visible=value;cancel.Enabled=true;}
 async void DownloadPlugin(object sender,EventArgs e){if(xpi!=null&&File.Exists(xpi)){System.Diagnostics.Process.Start("explorer.exe","/select,\""+xpi+"\"");return;}engine=new Engine();Busy(true);pluginBar.Visible=true;pluginBar.Value=0;engine.Progress=(phase,p)=>BeginInvoke(new Action(()=>{if(!busy)return;pluginBar.Value=p;status.Text=T("下载插件","Downloading XPI")+" · "+(int)(p*100)+"%";}));try{xpi=await Task.Run(()=>engine.DownloadPlugin(Setup.PluginDownloads()));Busy(false);RefreshText();pluginBar.Tint=Visual.Green;status.Text=T("插件已下载。打开文件，在 Zotero 中选择「从文件安装插件」。","XPI ready. Show the file, then choose Install Add-on From File in Zotero.");}catch(Exception error){Busy(false);status.Text=engine.Cancelled?T("已取消","Cancelled"):error.Message;}finally{engine.Dispose();engine=null;}}
 async void Start(object sender,EventArgs e){if(busy||!options.Any(o=>o.Checked))return;if(complete){System.Diagnostics.Process.Start("explorer.exe","/select,\""+xpi+"\"");return;}if(!File.Exists(Path.Combine(data,"zotero.sqlite"))){using(var dialog=new FolderBrowserDialog {Description=T("选择 Zotero 数据目录（包含 zotero.sqlite）","Choose the Zotero data folder (contains zotero.sqlite)"),ShowNewFolderButton=false}){if(dialog.ShowDialog()!=DialogResult.OK)return;data=dialog.SelectedPath;if(!File.Exists(Path.Combine(data,"zotero.sqlite")))return;if(!Directory.Exists(modelDirectory))modelDirectory=Setup.ModelRoot(data);}}if(complete){System.Diagnostics.Process.Start("explorer.exe","/select,\""+xpi+"\"");return;}completed.Clear();for(int i=0;i<options.Count;i++)if(options[i].Checked){modelBars[i].Value=0;modelBars[i].Visible=true;details[i].ForeColor=Visual.Muted;details[i].Text=T("等待下载","Waiting to download");}Busy(true);status.Text=T("正在准备…","Preparing…");var chosen=Setup.Models.Where((m,i)=>options[i].Checked).ToList();if(chosen.Count==0){Busy(false);return;}int modelIndex=0;engine=new Engine();engine.Progress=(phase,p)=>{int step=modelIndex;BeginInvoke(new Action(()=>{if(!busy)return;if(phase!="plugin"&&step<chosen.Count)UpdateCard(Setup.Models.IndexOf(chosen[step]),phase,p);else if(phase=="plugin"){pluginBar.Visible=true;pluginBar.Value=p;}var names=new Dictionary<string,string>{{"plugin",T("下载插件","Downloading plugin")},{"model",T("下载模型","Downloading model")},{"verify",T("校验模型","Verifying model")},{"install",T("安装模型","Installing model")},{"done",T("完成","Done")}};status.Text=(step+1)+"/"+chosen.Count+" · "+names[phase]+" · "+(int)(p*100)+"%";}));};try{foreach(var model in chosen){downloadBegan=DateTime.UtcNow;xpi=await Task.Run(()=>engine.Install(model,data,Setup.PluginDownloads(),modelDirectory));modelIndex++;}complete=true;Busy(false);RefreshText();}catch(Exception error){Busy(false);status.Text=engine.Cancelled?T("已取消，原有模型保留。","Cancelled. Existing model retained."):T("安装未完成，可重试。","Not completed. You can retry.");if(!engine.Cancelled)MessageBox.Show(this,error.Message,T("安装未完成","Installation not completed"),MessageBoxButtons.OK,MessageBoxIcon.Information);}finally{engine.Dispose();engine=null;}}
}
